import{_ as r,C as l,o,c as s,a2 as i,b as n,w as d,a as t,E as p,a3 as f,j as a}from"./chunks/framework.DZUUNQ77.js";const C=JSON.parse('{"title":"Reflect · 通用反射工具","description":"","frontmatter":{},"headers":[],"relativePath":"reference/helper/utils/reflect.md","filePath":"reference/helper/utils/reflect.md","lastUpdated":1784053534000}'),E={name:"reference/helper/utils/reflect.md"};function m(h,e,u,A,b,B){const c=l("Mermaid");return o(),s("div",null,[e[1]||(e[1]=i('<h1 id="reflect-·-通用反射工具" tabindex="-1">Reflect · 通用反射工具 <a class="header-anchor" href="#reflect-·-通用反射工具" aria-label="Permalink to &quot;Reflect · 通用反射工具&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/helper/utils/Reflect.java" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/helper/utils/Reflect.java</code></a></p></div><p><code>Reflect</code> 是一个<strong>通用反射工具类</strong>，提供链式 API 访问任意类的字段/方法/构造——不依赖 <code>@hide</code> 解封，只是把 JDK 反射的繁琐调用包成流畅接口。被 <code>VClientImpl</code>/<code>ResolverActivity</code>/<code>HackAppUtils</code>/<code>libcore MethodProxies</code>/<code>WifiManagerStub</code> 等广泛使用。</p><div class="warning custom-block"><p class="custom-block-title">不要与隐藏 API 解封混淆</p><p>Android 9+ 的隐藏 API 解封由外部库 <code>me.weishu.reflection.Reflection</code>（<a href="https://github.com/tiann/FreeReflection" target="_blank" rel="noreferrer"><code>me.weishu/reflection</code></a>）提供，<code>VirtualCore.startup()</code> 调 <code>Reflection.unseal(context)</code> 完成解封——<strong>那是另一个类，不是本文件</strong>。本 <code>Reflect</code> 工具类本身不解封隐藏 API，只在解封之后提供便捷反射访问。</p></div><h2 id="关键-api" tabindex="-1">关键 API <a class="header-anchor" href="#关键-api" aria-label="Permalink to &quot;关键 API&quot;">​</a></h2><p>链式入口与字段/方法访问：</p><table tabindex="0"><thead><tr><th>方法</th><th>作用</th></tr></thead><tbody><tr><td><code>on(String name)</code> / <code>on(String, ClassLoader)</code> / <code>on(Class)</code> / <code>on(Object)</code></td><td>创建反射句柄（按类名/类对象/实例）</td></tr><tr><td><code>field(name)</code> / <code>fields()</code></td><td>取字段；<code>fields()</code> 返回所有字段的 Reflect 映射</td></tr><tr><td><code>get()</code> / <code>get(name)</code></td><td>取实例值 / 取字段值</td></tr><tr><td><code>set(name, value)</code></td><td>设字段值</td></tr><tr><td><code>call(name)</code> / <code>call(name, args...)</code></td><td>调方法</td></tr><tr><td><code>exactMethod(name, types)</code></td><td>按精确签名取 Method</td></tr><tr><td><code>accessible(AccessibleObject)</code></td><td>静态工具：设可访问并返回</td></tr><tr><td><code>wrapper(Class)</code></td><td>基本类型 ↔ 包装类转换</td></tr></tbody></table><h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>各 Hook 用它快速读改目标对象的私有字段、调用隐藏方法，避免每次都写完整的 <code>Class.forName</code> + <code>getDeclaredField</code> + <code>setAccessible</code> 三段式。详见 <a href="./../../../features/mirror-reflection">反射框架 mirror</a>。</p><h2 id="反射访问流程" tabindex="-1">反射访问流程 <a class="header-anchor" href="#反射访问流程" aria-label="Permalink to &quot;反射访问流程&quot;">​</a></h2>',10)),(o(),n(f,null,{default:d(()=>[p(c,{id:"mermaid-109",class:"mermaid",graph:"flowchart%20LR%0A%20%20TARGET%5B%22%E7%9B%AE%E6%A0%87%E7%B1%BB%2F%E5%AE%9E%E4%BE%8B%22%5D%20--%3E%20ON%5B%22Reflect.on(target)%22%5D%0A%20%20ON%20--%3E%20FIELD%5B%22field(name)%2Fget(name)%2Fset(name%2Cv)%22%5D%0A%20%20ON%20--%3E%20CALL%5B%22call(name%2C%20args)%22%5D%0A%20%20ON%20--%3E%20FIELDS%5B%22fields()%20%E5%85%A8%E5%AD%97%E6%AE%B5%E6%98%A0%E5%B0%84%22%5D%0A%20%20FIELD%20--%3E%20ACCESS%5B%22accessible%20%E8%AE%BE%E5%8F%AF%E8%AE%BF%E9%97%AE%22%5D%0A%20%20CALL%20--%3E%20ACCESS%0A%20%20ACCESS%20--%3E%20RES%5B%22%E8%AF%BB%E6%94%B9%E7%A7%81%E6%9C%89%E6%88%90%E5%91%98%2F%E8%B0%83%E9%9A%90%E8%97%8F%E6%96%B9%E6%B3%95%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("p",null,[a("code",null,"accessible"),t(" 静态方法把 "),a("code",null,"setAccessible(true)"),t(" 的样板代码收敛成一行，是链式访问能穿透 private 的基础。")],-1))])}const _=r(E,[["render",m]]);export{C as __pageData,_ as default};
